import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { UsedVoucherCode } from "./used-voucher-code";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Used Voucher Code",
  component: UsedVoucherCode,
  parameters: {
    docs: {
      description: {
        component:
          "A voucher code that has been entered in the cart, with an optional description and a delete " +
          "button. The `variant` colors the row green for an accepted code or red for a rejected one; the " +
          "delete button reports clicks via `onDelete`.",
      },
    },
  },
  args: {
    code: "SUMMER2026",
    variant: "success",
    disabled: false,
    onDelete: fn(),
    description: { type: "description", text: "Summer campaign! 🌞" },
  },
} satisfies Meta<typeof UsedVoucherCode>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantSuccessAndError: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="variant" variantType="prop">
      <Variant label="success">
        <UsedVoucherCode {...args} />
      </Variant>
      <Variant label="error">
        <UsedVoucherCode
          {...args}
          variant="error"
          description={{ type: "description", text: "This voucher code is not valid." }}
        />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const VariantDescription: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="description" variantType="prop">
      <Variant label="description undefined">
        <UsedVoucherCode {...args} description={undefined} />
      </Variant>
      <Variant label="plain text">
        <UsedVoucherCode {...args} description={{ type: "description", text: "Summer campaign! 🌞" }} />
      </Variant>
      <Variant label="translated label (readMore)">
        <UsedVoucherCode {...args} description={{ type: "label", labelKey: "readMore" }} />
      </Variant>
      <Variant label="disabled delete button">
        <UsedVoucherCode {...args} disabled />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onDeleteSpy = fn();

export const TestDelete: Story = {
  args: {
    onDelete: onDeleteSpy,
  },
  play: async ({ canvasElement }) => {
    onDeleteSpy.mockClear();
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button", { name: "Ta bort rabattkod SUMMER2026" }));
    await expect(onDeleteSpy).toHaveBeenCalledTimes(1);
  },
};
